    revision:{icon:'↻',lens:'Recall strength',chart:'Confidence backlog',criteria:['Review interval','Confidence','Repeated mistakes']},
    assignments:{icon:'▣',lens:'Submission health',chart:'Status distribution',criteria:['Deadline risk','Submission stage','Feedback loop']},
    resources:{icon:'⌘',lens:'Resource value',chart:'Usefulness ranking',criteria:['Active use','Rating','Completion']},
    practice:{icon:'⚗',lens:'Deliberate practice',chart:'Accuracy curve',criteria:['Accuracy','Duration','Practice type']},
    projects:{icon:'◆',lens:'Delivery momentum',chart:'Milestone progress',criteria:['Progress','Blockers','Next milestone']},
    habits:{icon:'✓',lens:'Consistency system',chart:'Weekly adherence',criteria:['Today check-in','Weekly target','Streak stability']},
