  function appearanceMarkup(){const s={...state.settings},themes=[['nestlyra','Nestlyra Calm','#4C5FD5'],['auto','Automatic','#7181EA'],['dark','Midnight','#111d2e'],['ocean','Ocean','#1b9cff'],['cyber','Cyber','#ff3e9d'],['matrix','Matrix','#3cdb71'],['light','Classic Light','#dce8f5']];return `<div class="card-title"><h3>Appearance</h3><span>Personal to this account</span></div><div class="appearance-group"><h4>Theme</h4><div class="theme-list labeled">${themes.map(([name,label,color])=>`<button type="button" title="${label}" class="theme-chip ${s.theme===name?'active':''}" style="--swatch:${color}" onclick="setTheme('${name}')"><span>${label}</span></button>`).join('')}</div></div><div class="appearance-controls"><label>Text style<select onchange="updateAppearance('fontStyle',this.value)"><option value="modern" ${s.fontStyle==='modern'?'selected':''}>Modern — Inter + Poppins</option><option value="system" ${s.fontStyle==='system'?'selected':''}>System — Segoe UI</option><option value="editorial" ${s.fontStyle==='editorial'?'selected':''}>Editorial — Georgia</option></select></label><label>Interface text size<select onchange="updateAppearance('textScale',this.value)"><option value="compact" ${s.textScale==='compact'?'selected':''}>Compact</option><option value="normal" ${s.textScale==='normal'?'selected':''}>Comfortable</option><option value="large" ${s.textScale==='large'?'selected':''}>Large</option></select></label></div><p class="settings-note">The animated Nestlyra login scene is fixed for consistent branding. Add or remove your personal photo from Profile & account.</p>`}

