  window.groupSharingModal=()=>{if(typeof groupState==='undefined'||!groupState.selectedId)return toast('Open a group first');const config=groupConfig(groupState.selectedId);modal(`<div class="group-share-manager"><span class="eyebrow">SHARED RECORDS CONTROL</span><h2>Choose exactly what this group receives</h2><p>Turning a switch off stops future publication or hides that shared-record tool. Private titles, notes, files, applications and documents never enter aggregate progress.</p><nav class="group-share-tabs"><button class="active" data-share-tab="modules">Sections</button><button data-share-tab="fields">Data fields</button><button data-share-tab="records">Shared records</button></nav><div class="group-share-pages"><section data-share-page="modules">${GROUP_MODULES.map(id=>`<label><span><b>${id==='overall'?'◎':MODULE_META[id]?.[1]||'•'} ${h(id==='overall'?'Overall summary':MODULE_META[id]?.[0]||id)}</b><small>Aggregate only</small></span><input type="checkbox" data-share-option="modules" value="${id}" ${config.modules.includes(id)?'checked':''}></label>`).join('')}</section><section data-share-page="fields" class="hidden">${[['progress','Progress percentage'],['counts','Completed / total counts'],['study','Focused study minutes'],['mock','Mock-test average'],['activity','Active time, screen changes and presence']].map(([id,label])=>`<label><span><b>${h(label)}</b><small>${id==='activity'?'Requires activity sharing to be enabled':'No raw record names'}</small></span><input type="checkbox" data-share-option="fields" value="${id}" ${config.fields.includes(id)?'checked':''}></label>`).join('')}</section><section data-share-page="records" class="hidden">${[['task','Shared tasks'],['goal','Shared goals'],['plan','Shared plans'],['note','Short shared notes']].map(([id,label])=>`<label><span><b>${label}</b><small>Explicit co-edit record, separate from personal data</small></span><input type="checkbox" data-share-option="records" value="${id}" ${config.records.includes(id)?'checked':''}></label>`).join('')}</section></div><div class="modal-actions"><button class="btn ghost">Cancel</button><button type="button" class="btn primary" onclick="saveGroupSharingV37()">Save sharing choices</button></div></div>`);document.querySelectorAll('[data-share-tab]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-share-tab]').forEach(x=>x.classList.toggle('active',x===button));document.querySelectorAll('[data-share-page]').forEach(x=>x.classList.toggle('hidden',x.dataset.sharePage!==button.dataset.shareTab))})};
  window.saveGroupSharingV37=async()=>{const id=groupState.selectedId,config={};['modules','fields','records'].forEach(key=>config[key]=[...document.querySelectorAll(`[data-share-option="${key}"]:checked`)].map(x=>x.value));state.settings.groupShareConfigs=state.settings.groupShareConfigs||{};state.settings.groupShareConfigs[id]=config;save();if(sb&&cloudUser){const {error}=await sb.rpc('group_update_share_config',{p_group_id:id,p_config:config});if(error&&!/could not find|schema cache|does not exist/i.test(error.message))return toast(error.message)}closeModal();render();groupPublishProgress?.(true);toast('Sharing choices saved')};
  function groupRows(){return activeModules().map(moduleMetric).map(m=>({module_type:m.id,completed_count:m.complete,total_count:m.total,progress_percent:m.progress,study_minutes:m.id==='timer'?(state.activity||[]).reduce((s,x)=>s+Number(x.minutes||0),0):0,mock_average:m.id==='mocks'?m.progress:0,active_minutes:Math.round(Number(activityDay?.()?.activeMs||0)/60000),screen_changes:Number(activityDay?.()?.viewChanges||0),last_seen:new Date().toISOString()}))}

